/**
 * Lists the types in name order. With {@code counts=true} it answers {@code type, instances} by instance count (most
 * first, then name), or {@code counts-timed-out} when counting takes longer than two seconds.
 */
public class TypesServlet extends TupleServlet {

	public TypesServlet() {
		super("type");
	}

	private static final String DISTINCT_TYPE = "SELECT DISTINCT ?type WHERE { ?subj a ?type }";

	private static final String TYPE_COUNTS = "SELECT ?type (COUNT(?s) AS ?instances) WHERE { ?s a ?type } GROUP BY ?type";

	private static final Comparator<Value[]> BY_INSTANCES_THEN_NAME = Comparator
			.comparingLong((Value[] row) -> ((Literal) row[1]).longValue())
			.reversed()
			.thenComparing(row -> row[0], BrowseList.BY_NAME);

	private final BrowseList browseList = new BrowseList();

	@Override
	protected String[] variables(WorkbenchRequest req) {
		return BrowseList.countsRequested(req) ? new String[] { "type", "instances" } : variables;
	}

	@Override
	protected void service(WorkbenchRequest req, HttpServletResponse resp, TupleResultBuilder builder,
			RepositoryConnection con) throws Exception {
		String filter = BrowseList.filter(req);
		BrowseList.echoFilter(builder, filter);
		if (BrowseList.countsRequested(req)) {
			counts(builder, BrowseList.matching(filter));
		} else {
			list(builder, con, BrowseList.matching(filter));
		}
	}

	@Override
	protected void service(TupleResultBuilder builder, RepositoryConnection con) throws Exception {
		list(builder, con, BrowseList.matching(""));
	}

	private void list(TupleResultBuilder builder, RepositoryConnection con, Predicate<Value> filter)
			throws Exception {
		List<Value> types = new ArrayList<>();
		TupleQuery query = con.prepareTupleQuery(SPARQL, DISTINCT_TYPE);
		try (TupleQueryResult result = query.evaluate()) {
			while (result.hasNext()) {
				Value type = result.next().getValue("type");
				if (type != null && filter.test(type)) {
					types.add(type);
				}
			}
		}
		types.sort(BrowseList.BY_NAME);
		for (Value type : types) {
			builder.result(type);
		}
	}

	private void counts(TupleResultBuilder builder, Predicate<Value> filter) throws Exception {
		Optional<List<Value[]>> counts = browseList.withinBudget(() -> {
			List<Value[]> rows = new ArrayList<>();
			try (RepositoryConnection connection = repository.getConnection()) {
				TupleQuery query = connection.prepareTupleQuery(SPARQL, TYPE_COUNTS);
				query.setMaxExecutionTime(BrowseList.COUNT_BUDGET_SECONDS);
				try (TupleQueryResult result = query.evaluate()) {
					while (result.hasNext()) {
						BindingSet bindings = result.next();
						Value type = bindings.getValue("type");
						if (type != null && filter.test(type)) {
							rows.add(new Value[] { type, bindings.getValue("instances") });
						}
					}
				}
			}
			return rows;
		});
		if (counts.isEmpty()) {
			BrowseList.countsTimedOut(builder);
			return;
		}
		List<Value[]> rows = counts.get();
		rows.sort(BY_INSTANCES_THEN_NAME);
		for (Value[] row : rows) {
			builder.result((Object[]) row);
		}
	}

	@Override
	public void destroy() {
		browseList.shutdown();
		super.destroy();
	}
}
